class Solution:
    def generateParenthesis(self, n: int) -> List[str]:
        if n == 0:
            return []
        if n == 1:
            return ['()']

        # 递归生成左括号和右括号
        left = self.generateParenthesis(n - 1)
        right = self.generateParenthesis(n - 2)

        # 将左右括号组合成所有可能的组合
        result = []
        for l in left:
            for r in right:
                result.append(f'({l}){r}')

        return result
```

