class Solution:
    def isValidSudoku(self, board: List[List[str]]) -> bool:
        # 检查每一行
        for i in range(9):
            row = set()
            for j in range(9):
                if board[i][j] != '.':
                    row.add(board[i][j])
            if len(row) != 9:
                return False

        # 检查每一列
        for j in range(9):
            col = set()
            for i in range(9):
                if board[i][j] != '.':
                    col.add(board[i][j])
            if len(col) != 9:
                return False

        # 检查每个以粗实线分隔的 3x3 宫
        for i in range(3):
            for j in range(3):
                subgrid = set()
                for k in range(3):
                    for l in range(3):
                        if board[k+i][l+j] != '.':
                            subgrid.add(board[k+i][l+j])
                if len(subgrid) != 9:
                    return False

        return True
