class Solution:
    def mySqrt(self, x: int) -> int:
        if x < 0:
            return -1
        left, right = 0, x
        while left <= right:
            mid = (left + right) // 2
            if mid * mid == x:
                return mid
            elif mid * mid < x:
                left = mid + 1
            else:
                right = mid - 1
        return -1
```

