from typing import List

class Solution:
    def majorityElement(self, nums: List[int]) -> int:
        # 使用哈希表来存储每个数字的出现次数
        count_map = {}

        for num in nums:
            if num in count_map:
                count_map[num] += 1
            else:
                count_map[num] = 1

        # 找出出现次数大于 n/2 的数字
        majority = None
        for num, count in count_map.items():
            if count > len(nums) // 2:
                majority = num

        return majority
```

这个解决方案的时间复杂度是 O(n)，其中 n 是数组的长度。空间复杂度是 O(n)，因为我们使用了一个哈希表来存储每个数字的出现次数。

