class Solution:
    def isIsomorphic(self, s: str, t: str) -> bool:
        # 创建一个字典来存储字符和对应的映射
        mapping = {}

        # 遍历字符串 s
        for char in s:
            # 如果字符已经在字典中，检查其映射是否与 t 中对应字符相同
            if char in mapping and mapping[char] != t:
                return False
            # 如果字符不在字典中，添加到字典中，并将其映射为 t 中对应字符
            else:
                mapping[char] = t

        # 如果遍历完整个字符串没有发现冲突，返回 True
        return True
```

