class Solution:
    def summaryRanges(self, nums: List[int]) -> List[str]:
        if not nums:
            return []

        ranges = []
        start = nums[0]
        for end in nums[1:]:
            if end - start > 1:
                ranges.append(f"{start}->{end}")
            start = end

        return ranges
