class Solution:
    def canConstruct(self, ransomNote: str, magazine: str) -> bool:
        # 创建一个字典来存储杂志中每个字符的出现次数
        magazine_count = {}

        # 遍历杂志中的每个字符
        for char in magazine:
            # 如果字符已经在字典中，增加其出现次数
            if char in magazine_count:
                magazine_count[char] += 1
            else:
                # 如果字符不在字典中，添加到字典中，并设置为1
                magazine_count[char] = 1

        # 遍历 ransomNote中的每个字符
        for char in ransomNote:
            # 如果字符不在字典中，返回 False
            if char not in magazine_count:
                return False

            # 如果字符在字典中且出现次数大于0，则减少该字符的出现次数
            if magazine_count[char] > 0:
                magazine_count[char] -= 1
            else:
                # 如果字符在字典中且出现次数小于0，则返回 False
                return False

        # 如果所有字符都已成功添加到字典中，返回 True
        return True
